SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;

IF COL_LENGTH('dbo.HangHoa', 'MauSac') IS NULL EXEC(N'ALTER TABLE dbo.HangHoa ADD MauSac NVARCHAR(30) NULL;');
IF COL_LENGTH('dbo.HangHoa', 'ChatLieu') IS NULL EXEC(N'ALTER TABLE dbo.HangHoa ADD ChatLieu NVARCHAR(80) NULL;');
IF COL_LENGTH('dbo.HangHoa', 'KichThuoc') IS NULL EXEC(N'ALTER TABLE dbo.HangHoa ADD KichThuoc NVARCHAR(80) NULL;');
IF COL_LENGTH('dbo.HangHoa', 'BaoHanh') IS NULL EXEC(N'ALTER TABLE dbo.HangHoa ADD BaoHanh NVARCHAR(40) NULL;');
IF COL_LENGTH('dbo.HangHoa', 'PhongCach') IS NULL EXEC(N'ALTER TABLE dbo.HangHoa ADD PhongCach NVARCHAR(50) NULL;');
GO

BEGIN TRY
    BEGIN TRAN;

    SET IDENTITY_INSERT dbo.Loai ON;
    MERGE dbo.Loai AS target
