    SET IDENTITY_INSERT dbo.Loai OFF;

    MERGE dbo.NhaCungCap AS target
    USING (VALUES
        (N'NCC001', N'Atelier Living', N'ncc-saoviet.png', N'John Nguyen', N'atelier.living@hshop.local', N'0901000001', N'District 1, HCMC', N'Curated supplier for sofas, tables and premium home styling items.'),
        (N'NCC002', N'Urban Utility', N'ncc-minhan.png', N'Tracy Tran', N'urban.utility@hshop.local', N'0901000002', N'Thu Duc, HCMC', N'Supplier of functional storage, travel-ready goods and compact productivity products.'),
