    MERGE dbo.TrangThai AS target
    USING (VALUES
        (0, N'New', N'Order has been created.'),
        (1, N'Pending Confirmation', N'Order is waiting for staff confirmation.'),
        (2, N'Shipping', N'Order is being delivered.'),
        (3, N'Completed', N'Order has been delivered successfully.'),
        (4, N'Cancelled', N'Order has been cancelled.')
    ) AS src (MaTrangThai, TenTrangThai, MoTa)
    ON target.MaTrangThai = src.MaTrangThai
    WHEN MATCHED THEN UPDATE SET TenTrangThai=src.TenTrangThai, MoTa=src.MoTa
    WHEN NOT MATCHED BY TARGET THEN INSERT (MaTrangThai, TenTrangThai, MoTa) VALUES (src.MaTrangThai, src.TenTrangThai, src.MoTa);

