    SET IDENTITY_INSERT dbo.HangHoa OFF;

    MERGE dbo.KhachHang AS target
    USING (VALUES
        (N'admin', N'Administrator', CAST(1 AS bit), CAST('1990-01-01' AS datetime), N'Admin Address', N'0900000000', N'admin@hshop.local', N'Photo.gif', N'52968bfa80ccf71df5e1dc38df716666', N'A1B2C3', CAST(1 AS bit), 1)
    ) AS src (MaKH, HoTen, GioiTinh, NgaySinh, DiaChi, DienThoai, Email, Hinh, MatKhau, RandomKey, HieuLuc, VaiTro)
    ON target.MaKH = src.MaKH
    WHEN MATCHED THEN UPDATE SET HoTen=src.HoTen, GioiTinh=src.GioiTinh, NgaySinh=src.NgaySinh, DiaChi=src.DiaChi, DienThoai=src.DienThoai, Email=src.Email, Hinh=src.Hinh, MatKhau=src.MatKhau, RandomKey=src.RandomKey, HieuLuc=src.HieuLuc, VaiTro=src.VaiTro
    WHEN NOT MATCHED BY TARGET THEN INSERT (MaKH, HoTen, GioiTinh, NgaySinh, DiaChi, DienThoai, Email, Hinh, MatKhau, RandomKey, HieuLuc, VaiTro) VALUES (src.MaKH, src.HoTen, src.GioiTinh, src.NgaySinh, src.DiaChi, src.DienThoai, src.Email, src.Hinh, src.MatKhau, src.RandomKey, src.HieuLuc, src.VaiTro);

    UPDATE c SET DonGia = h.DonGia
    FROM dbo.ChiTietHD c
    INNER JOIN dbo.HangHoa h ON h.MaHH = c.MaHH;

    COMMIT TRAN;
    SELECT N'[SEED_OK]' AS Msg, 'Loai' AS Tbl, COUNT(*) AS Cnt FROM dbo.Loai
    UNION ALL SELECT N'[SEED_OK]', 'NhaCungCap', COUNT(*) FROM dbo.NhaCungCap
    UNION ALL SELECT N'[SEED_OK]', 'TrangThai', COUNT(*) FROM dbo.TrangThai
    UNION ALL SELECT N'[SEED_OK]', 'HangHoa', COUNT(*) FROM dbo.HangHoa
    UNION ALL SELECT N'[SEED_OK]', 'KhachHang', COUNT(*) FROM dbo.KhachHang
    UNION ALL SELECT N'[SEED_OK]', 'LuxuryWebImages', COUNT(*) FROM dbo.HangHoa WHERE Hinh LIKE N'lux-%';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRAN;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(N'Seed failed: %s', 16, 1, @Err);
END CATCH;
